37	const GemmImpl &ResolveGemmImpl(Target target) {
38	  const auto &registry = GemmImplRegistry();
39	  const GemmImpl *matched_impl = nullptr;
40	  for (const GemmImpl &impl : registry) {
41	    if (impl.match_target(target)) {
42	      ICHECK(matched_impl == nullptr)
43	          << "tl.gemm found multiple target-specific implementations for "
44	          << target->str() << ": " << matched_impl->name << " and "
45	          << impl.name;
46	      matched_impl = &impl;
47	    }
48	  }
49	  ICHECK(matched_impl != nullptr)
50	      << "tl.gemm requires a target-specific implementation, but no gemm "
51	         "implementation is registered for "
52	      << target->str();
53	  return *matched_impl;
54	}
55	
56	} // namespace
