58	void RegisterGemmImpl(GemmImpl impl) {
59	  ICHECK(impl.name != nullptr);
60	  ICHECK(impl.match_target != nullptr);
61	  ICHECK(impl.select_inst != nullptr);
62	  ICHECK(impl.compute_warp_partition != nullptr);
63	  ICHECK(impl.reuse_existing_shared_layout != nullptr);
64	  GemmImplRegistry().push_back(impl);
65	}
