67	/**
68	 * @brief Construct a Gemm operator from serialized TL arguments.
69	 *
70	 * Deserializes operator parameters from `args` and resolves buffer references,
71	 * populating an internal GemmNode with buffers, transpose flags, M/N/K,
72	 * warp policy, clear_accum, strides, offsets, optional kPack/wg_wait, and
73	 * optional mbarrier.
74	 *
75	 * @param args Positional serialized arguments produced by the TL frontend:
76	 *   expected layout is:
77	 *     [Aptr, Bptr, Cptr, trans_A (Bool), trans_B (Bool),
78	 *      M (Int), N (Int), K (Int), policy (Int), clear_accum (Bool),
79	 *      stride_A (Int), stride_B (Int), offset_A (Int), offset_B (Int),
80	 *      (optional) kPack (Int), (optional) internal wg_wait (Int),
81	 *      (optional) mbar (BufferLoad), cCoord_y (PrimExpr), cCoord_x (PrimExpr)]
82	 */
83	Gemm::Gemm(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
84	  ObjectPtr<GemmNode> node = make_object<GemmNode>();
85	
86	  auto a_access = NormalizeToAccessRegion(args[0], kAccessRead);
87	  auto b_access = NormalizeToAccessRegion(args[1], kAccessRead);
88	  auto c_access = NormalizeToAccessRegion(args[2], kAccessReadWrite);
89	
90	  node->aRegion_ = a_access.region;
91	  node->bRegion_ = b_access.region;
92	  node->cRegion_ = c_access.region;
93	  node->SetAccessRegions({a_access, b_access, c_access});
94	
95	  node->a_ = node->aRegion_->buffer;
96	  node->b_ = node->bRegion_->buffer;
97	  node->c_ = node->cRegion_->buffer;
98	  node->transA_ = args[3].as<Bool>().value();
99	  node->transB_ = args[4].as<Bool>().value();
100	  node->m_ = args[5].as<IntImm>().value()->value;
101	  node->n_ = args[6].as<IntImm>().value()->value;
102	  node->k_ = args[7].as<IntImm>().value()->value;
103	  node->policy_ = GemmWarpPolicy(args[8].as<IntImm>().value()->value);
104	  node->clearAccum_ = args[9].as<PrimExpr>().value();
105	  node->strideA_ = args[10].as<IntImm>().value()->value;
106	  node->strideB_ = args[11].as<IntImm>().value()->value;
107	  node->offsetA_ = args[12].as<PrimExpr>().value();
108	  node->offsetB_ = args[13].as<PrimExpr>().value();
109	  if (args.size() > 14) {
110	    node->kPack_ = args[14].as<IntImm>().value()->value;
111	    if (node->kPack_ != 1 && node->kPack_ != 2) {
112	      ICHECK(false) << "kPack must be 1 or 2";
113	    }
114	  }
115	  if (args.size() > 15) {
116	    node->wgWait_ = args[15].as<IntImm>().value()->value;
117	  }
118	  if (auto val = annotations.Get("is_wgmma")) {
119	    const auto *int_val = val->as<IntImmNode>();
120	    ICHECK(int_val) << "is_wgmma annotation must be IntImmNode";
121	    node->isWgmma_ = int_val->value != 0;
122	  }
123	  if (auto val = annotations.Get("is_tcgen05")) {
124	    const auto *int_val = val->as<IntImmNode>();
125	    ICHECK(int_val) << "is_tcgen05 annotation must be IntImmNode";
126	    node->isTcgen05_ = int_val->value != 0;
127	  }
128	  if (args.size() > 16 && args[16]->IsInstance<BufferLoadNode>()) {
129	    node->mbar_ = Downcast<BufferLoad>(args[16]);
130	  }
131	  node->cCoords_ = Array<PrimExpr>(
132	      {args[17].as<PrimExpr>().value(), args[18].as<PrimExpr>().value()});
133	  if (args.size() > 19) {
134	    node->sfaRegion_ = NormalizeToBufferRegion(args[19]);
135	  }
136	  if (args.size() > 20) {
137	    node->sfbRegion_ = NormalizeToBufferRegion(args[20]);
138	  }
139	  if (args.size() > 21) {
140	    node->sfKStart_ = args[21].as<PrimExpr>().value();
141	  }
142	  node->annotations_ = annotations;
143	  data_ = std::move(node);
144	}
