146	AccessRegions GemmNode::GetAccessRegions() const {
147	  AccessRegions result;
148	  result.reads.push_back(aRegion_);
149	  result.reads.push_back(bRegion_);
150	  if (!is_one(clearAccum_)) {
151	    result.reads.push_back(cRegion_);
152	  }
153	  if (sfaRegion_.defined()) {
154	    result.reads.push_back(sfaRegion_);
155	  }
156	  if (sfbRegion_.defined()) {
157	    result.reads.push_back(sfbRegion_);
158	  }
159	  result.writes.push_back(cRegion_);
160	  return result;
161	}
