172	std::pair<int, int> GemmWarpPolicyNode::ComputeWarpPartition(
173	    int M, int N, int block_size, Target target, String gemm_inst) const {
174	  return ResolveGemmImpl(target).compute_warp_partition(*this, M, N, block_size,
175	                                                        target, gemm_inst);
176	}
