178	Stmt GemmNode::Lower(const LowerArgs &lower_args,
179	                     arith::Analyzer *analyzer) const {
180	  if (const auto f = Function::GetGlobal("tl.gemm.lower")) {
181	    PrimExpr mbar_phase = lower_args.mbar_phase_expr;
182	    if (auto explicit_phase = GetAnnotatedMbarPhaseExpr(annotations_)) {
183	      mbar_phase = explicit_phase.value();
184	    }
185	    // NOTE(wt): Decide the instruction key and compute warp partition on Python
186	    // side.
187	    auto prim_func = Downcast<PrimFunc>(
188	        (*f)(GetRef<Gemm>(this), lower_args.layout_map, lower_args.target,
189	             lower_args.thread_bounds, lower_args.thread_var, mbar_phase));
190	    ICHECK(prim_func->attrs.defined());
191	    auto global_symbol = prim_func->attrs.GetAttr<String>("global_symbol");
192	    ICHECK(global_symbol.has_value());
193	    if (prim_func->body.as<SBlockRealizeNode>()) {
194	      SBlockRealize block_realize = Downcast<SBlockRealize>(prim_func->body);
195	      auto block = block_realize->block;
196	      {
197	        SBlockNode *n = block.CopyOnWrite();
198	        n->name_hint = global_symbol.value();
199	        n->annotations.Set(tl::attr::kLexicalAllocScope,
200	                           IntImm(DataType::Int(32), 1));
201	      }
202	      return SBlockRealize(block_realize->iter_values, block_realize->predicate,
203	                           block);
204	    }
205	    // wrap with block realize node
206	    Map<String, ObjectRef> block_annotations;
207	    block_annotations.Set(tl::attr::kLexicalAllocScope,
208	                          IntImm(DataType::Int(32), 1));
209	    return SBlockRealize(
210	        /*iter_values=*/Array<PrimExpr>(),
211	        /*predicate=*/const_true(),
212	        /*block=*/
213	        SBlock(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
214	               /*name_hint=*/global_symbol.value(), prim_func->body,
215	               /*init=*/Optional<Stmt>(), /*alloc_buffers=*/{},
216	               /*match_buffers=*/{}, /*annotations=*/block_annotations));
217	  } else {
218	    LOG(FATAL) << "No lower function found for gemm";
219	    return Stmt();
220	  }
221	}
222	
223	LayoutMap GemmNode::InferLayout(const LayoutInferArgs &layout_args,
224	                                InferLevel level) const {
225	  if (completed_)
226	    return {};
227	  LayoutMap results;
228	  if (const auto f = Function::GetGlobal("tl.gemm.infer_layout")) {
229	    auto inferred_layouts = Downcast<LayoutMap>((*f)(
230	        GetRef<Gemm>(this), layout_args.target, layout_args.thread_bounds));
231	    // For MMA instructions, skip shared buffer layouts that are already
232	    // inferred by a prior operator to avoid layout conflicts when the same
233	    // shared buffer is consumed by multiple gemm ops with different transpose
234	    // semantics. WGMMA/TCGEN5MMA have strict shared memory layout requirements
235	    // and must always set their layouts.
236	    auto block_size = *as_const_int(layout_args.thread_bounds->extent);
237	    String gemm_inst = GetGemmInstructionKey(block_size, layout_args.target);
238	    bool reuse_existing_shared_layout =
239	        ResolveGemmImpl(layout_args.target)
240	            .reuse_existing_shared_layout(gemm_inst);
241	    for (auto kv : inferred_layouts) {
242	      const Buffer &buf = kv.first;
243	      const Layout &layout = kv.second;
244	      if (reuse_existing_shared_layout && IsSharedBuffer(buf) &&
245	          layout_args.layout_map.count(buf)) {
246	        continue;
247	      }
248	      if (auto frag = layout.as<Fragment>()) {
249	        results.Set(buf,
250	                    frag.value()->BindThreadRange(layout_args.thread_bounds));
251	      } else {
252	        results.Set(buf, layout);
253	      }
254	    }
255	  } else {
256	    LOG(FATAL) << "No infer layout function found for gemm";
257	  }
258	
259	  completed_ = true;
260	  return results;
261	}
262	
263	TIR_REGISTER_TL_TILE_OP(Gemm, gemm)
264	    .set_num_inputs(-1)
265	    .set_attr<TCallEffectKind>("TCallEffectKind",
266	                               Integer(CallEffectKind::kOpaque));
267	
268	TVM_REGISTER_OP("tl.tileop.wgmma_gemm")
269	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "wgmma_gemm")
270	    .set_attr<OpBuilderFunc>("TLOpBuilder",
271	                             [](Array<PrimExpr> args,
272	                                Map<String, ObjectRef> annotations) {
273	                               Map<String, ObjectRef> ann = annotations;
274	                               ann.Set("is_wgmma",
275	                                       IntImm(DataType::Int(32), 1));
276	                               return Gemm(args, ann);
277	                             })
278	    .set_num_inputs(-1)
279	    .set_attr<TCallEffectKind>("TCallEffectKind",
280	                               Integer(CallEffectKind::kOpaque));
281	
282	TVM_REGISTER_OP("tl.tileop.tcgen05_gemm")
283	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "tcgen05_gemm")
284	    .set_attr<OpBuilderFunc>("TLOpBuilder",
285	                             [](Array<PrimExpr> args,
286	                                Map<String, ObjectRef> annotations) {
287	                               Map<String, ObjectRef> ann = annotations;
288	                               ann.Set("is_tcgen05",
289	                                       IntImm(DataType::Int(32), 1));
290	                               return Gemm(args, ann);
291	                             })
292	    .set_num_inputs(-1)
293	    .set_attr<TCallEffectKind>("TCallEffectKind",
294	                               Integer(CallEffectKind::kOpaque));
295	
296	TVM_REGISTER_OP("tl.GemmWarpPolicy")
297	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "GemmWarpPolicy");
298	
299	TVM_FFI_STATIC_INIT_BLOCK() {
300	  GemmNode::RegisterReflection();
301	  GemmWarpPolicyNode::RegisterReflection();
302	  namespace refl = reflection;
303	  refl::GlobalDef().def("tl.GemmWarpPolicyComputeWarpPartition",
304	                        [](GemmWarpPolicy policy, int M, int N, int block_size,
305	                           Target target, String gemm_inst) {
306	                          policy->ComputeWarpPartition(M, N, block_size, target,
307	                                                       gemm_inst);
308	                        });
309	  refl::GlobalDef().def("tl.GemmGetGemmInstructionKey",
310	                        [](Gemm gemm, int block_size, Target target) {
311	                          return gemm->GetGemmInstructionKey(block_size,
312	                                                             target);
313	                        });
314	}
