117	std::pair<int, int>
118	ComputeDefaultWarpPartition(const GemmWarpPolicyNode &policy, int M, int N,
119	                            int num_warps, int k_n_per_warp) {
120	  int m_warp = 1, n_warp = 1;
121	  constexpr int kMPerWarp = 16;
122	
123	  ICHECK(M % kMPerWarp == 0)
124	      << "M must be divisible by " << kMPerWarp << ", but got " << M;
125	  ICHECK(N % k_n_per_warp == 0)
126	      << "N must be divisible by " << k_n_per_warp << ", but got " << N;
127	
128	  if (policy.IsFullRow()) {
129	    m_warp = num_warps;
130	    n_warp = 1;
131	    if (M % (m_warp * kMPerWarp) != 0) {
132	      int max_m_warps = M / kMPerWarp;
133	      m_warp = max_m_warps;
134	      n_warp = num_warps / m_warp;
135	      if (n_warp == 0)
136	        n_warp = 1;
137	    }
138	  } else if (policy.IsFullCol()) {
139	    m_warp = 1;
140	    n_warp = num_warps;
141	    if (N % (n_warp * k_n_per_warp) != 0) {
142	      int max_n_warps = N / k_n_per_warp;
143	      n_warp = max_n_warps;
144	      m_warp = num_warps / n_warp;
145	      if (m_warp == 0)
146	        m_warp = 1;
147	    }
148	  } else if (policy.IsSquare()) {
149	    int max_m_warps = M / kMPerWarp;
150	    float ideal_ratio = N > 0 ? static_cast<float>(M) / N : 1.0f;
151	
152	    int best_m = 1;
153	    int best_n = 1;
154	    float best_balance = std::numeric_limits<float>::max();
155	    for (int m = 1; m <= max_m_warps && m <= num_warps; m++) {
156	      int n = num_warps / m;
157	
158	      float m_per_warp = static_cast<float>(M) / (m * kMPerWarp);
159	      float n_per_warp = static_cast<float>(N) / (n * k_n_per_warp);
160	      if (m_per_warp < 1 || n_per_warp < 1)
161	        continue;
162	      if (m * n != num_warps)
163	        continue;
164	
165	      float balance = std::abs(m_per_warp / n_per_warp - ideal_ratio);
166	      if (balance < best_balance) {
167	        best_balance = balance;
168	        best_m = m;
169	        best_n = n;
170	      }
171	    }
172	
173	    m_warp = best_m;
174	    n_warp = best_n;
175	  } else {
176	    ICHECK(0) << "Unknown GemmWarpPolicy";
177	  }
178	
179	  ICHECK(m_warp * n_warp == num_warps)
180	      << "m_warp * n_warp must equal num_warps, m_warp: " << m_warp
181	      << ", n_warp: " << n_warp << ", num_warps: " << num_warps;
182	  policy.m_warp = m_warp;
183	  policy.n_warp = n_warp;
184	  return {m_warp, n_warp};
185	}
