/*!
 * \file tl/op/gemm.h
 * \brief Define gemm operator.
 *
 */

#ifndef TVM_TL_OP_GEMM_H_
#define TVM_TL_OP_GEMM_H_

#include "operator.h"
#include "support/check.h"

#include <utility>

namespace tvm {

namespace tl {

using namespace tirx;
using namespace ffi;

enum class GemmWarpPolicyType : uint8_t {
  kSquare = 0,
  kFullRow = 1,
  kFullCol = 2,
  kFree = 3,
};

/// Convert GemmWarpPolicyType enum to string for debugging
inline const char *GemmWarpPolicyTypeToString(GemmWarpPolicyType type) {
  switch (type) {
  case GemmWarpPolicyType::kSquare:
    return "Square";
  case GemmWarpPolicyType::kFullRow:
    return "FullRow";
  case GemmWarpPolicyType::kFullCol:
    return "FullCol";
  case GemmWarpPolicyType::kFree:
    return "Free";
  default:
    return "Unknown";
  }
}

class GemmWarpPolicyNode : public Object {
public:
  mutable int m_warp{0};
  mutable int n_warp{0};
  int policy_type;

  TVM_FFI_DECLARE_OBJECT_INFO("tl.GemmWarpPolicy", GemmWarpPolicyNode, Object);

  static void RegisterReflection() {
    namespace refl = reflection;
    refl::ObjectDef<GemmWarpPolicyNode>()
        .def_ro("policy_type", &GemmWarpPolicyNode::policy_type)
        .def_ro("m_warp", &GemmWarpPolicyNode::m_warp)
        .def_ro("n_warp", &GemmWarpPolicyNode::n_warp);
  }

  std::pair<int, int> ComputeWarpPartition(int M, int N, int block_size,
                                           Target target,
                                           String gemm_inst) const;

  bool IsSquare() const {
    return policy_type == int(GemmWarpPolicyType::kSquare);
  }
  bool IsFullRow() const {
    return policy_type == int(GemmWarpPolicyType::kFullRow);
  }
  bool IsFullCol() const {
    return policy_type == int(GemmWarpPolicyType::kFullCol);
  }
  bool IsFree() const { return policy_type == int(GemmWarpPolicyType::kFree); }
};

class GemmWarpPolicy : public ObjectRef {
public:
  TVM_FFI_DEFINE_OBJECT_REF_METHODS_NULLABLE(GemmWarpPolicy, ObjectRef,
                                             GemmWarpPolicyNode);

  explicit GemmWarpPolicy(GemmWarpPolicyType policy_type) {
    auto node = make_object<GemmWarpPolicyNode>();
    node->policy_type = (int)policy_type;
    data_ = std::move(node);
  }

  explicit GemmWarpPolicy(int policy_type) {
    auto node = make_object<GemmWarpPolicyNode>();
    node->policy_type = policy_type;
    data_ = std::move(node);
  }

  explicit GemmWarpPolicy(int m_warp, int n_warp) {
    auto node = make_object<GemmWarpPolicyNode>();
    node->m_warp = m_warp;
    node->n_warp = n_warp;
    node->policy_type = (int)GemmWarpPolicyType::kFree;
    data_ = std::move(node);
  }
};

class GemmNode : public TileOperatorNode {
public:
  tirx::Buffer a_, b_, c_;
  // BufferRegion for A, B and C
  BufferRegion aRegion_, bRegion_, cRegion_;
  bool transA_, transB_;
  int m_, n_, k_;
  int strideA_, strideB_;
  // Offsets may be symbolic (e.g. a sliced operand B[:, j*64:...] in a loop).
  PrimExpr offsetA_, offsetB_;
  PrimExpr clearAccum_ = const_false();
  tirx::BufferLoad mbar_; // mbar is optional, only used for TCGEN5MMA
  Array<PrimExpr> cCoords_;
  // k_pack please ref to bitblas/tl/mfma_macro_generator.py::k_pack
  // only will be enabled under cdna mfma instructions
  int kPack_ = 1;
  int wgWait_ = 0;
  bool isWgmma_ = false;
  bool isTcgen05_ = false;
  mutable GemmWarpPolicy policy_;
  Map<String, ObjectRef> annotations_;
  BufferRegion sfaRegion_, sfbRegion_;
  PrimExpr sfKStart_;

  TVM_FFI_DECLARE_OBJECT_INFO_FINAL("tl.Gemm", GemmNode, TileOperatorNode);

  static void RegisterReflection() {
    namespace refl = reflection;
    refl::ObjectDef<GemmNode>()
        .def_ro("a", &GemmNode::a_)
        .def_ro("b", &GemmNode::b_)
        .def_ro("c", &GemmNode::c_)
        .def_ro("aRegion", &GemmNode::aRegion_)
        .def_ro("bRegion", &GemmNode::bRegion_)
        .def_ro("cRegion", &GemmNode::cRegion_)
        .def_ro("transA", &GemmNode::transA_)
        .def_ro("transB", &GemmNode::transB_)
        .def_ro("m", &GemmNode::m_)
        .def_ro("n", &GemmNode::n_)
        .def_ro("k", &GemmNode::k_)
        .def_ro("strideA", &GemmNode::strideA_)
        .def_ro("strideB", &GemmNode::strideB_)
        .def_ro("offsetA", &GemmNode::offsetA_)
        .def_ro("offsetB", &GemmNode::offsetB_)
        .def_ro("clearAccum", &GemmNode::clearAccum_)
        .def_ro("mbar", &GemmNode::mbar_)
        .def_ro("cCoords", &GemmNode::cCoords_)
        .def_ro("kPack", &GemmNode::kPack_)
        .def_ro("wgWait", &GemmNode::wgWait_)
        .def_ro("isWgmma", &GemmNode::isWgmma_)
        .def_ro("isTcgen05", &GemmNode::isTcgen05_)
        .def_ro("policy", &GemmNode::policy_)
        .def_ro("annotations", &GemmNode::annotations_)
        .def_ro("sfaRegion", &GemmNode::sfaRegion_)
        .def_ro("sfbRegion", &GemmNode::sfbRegion_)
        .def_ro("sfKStart", &GemmNode::sfKStart_);
  }

  Stmt Lower(const LowerArgs &lower_args,
             arith::Analyzer *analyzer) const override;
  LayoutMap InferLayout(const LayoutInferArgs &layout_args,
                        InferLevel level) const override;
  AccessRegions GetAccessRegions() const override;

  TileOperator Clone() const;

  // Target-specific GEMM instruction key.
  String GetGemmInstructionKey(int block_size, Target target) const;

private:
  mutable bool completed_ = false;
};

using GemmTargetPredicate = bool (*)(Target target);

struct GemmImpl {
  const char *name;
  GemmTargetPredicate match_target;

  String (*select_inst)(const GemmNode &op, int block_size, Target target);

  std::pair<int, int> (*compute_warp_partition)(
      const GemmWarpPolicyNode &policy, int M, int N, int block_size,
      Target target, String gemm_inst);

  bool (*reuse_existing_shared_layout)(String gemm_inst);
};

void RegisterGemmImpl(GemmImpl impl);

class Gemm : public TileOperator {
public:
  TVM_FFI_DEFINE_OBJECT_REF_METHODS_NULLABLE(Gemm, TileOperator, GemmNode);
  TVM_DLL Gemm(Array<PrimExpr> args,
               Map<String, ObjectRef> annotations = Map<String, ObjectRef>());
  static const Op &Get();
};

} // namespace tl
} // namespace tvm

#endif //  TVM_TL_OP_GEMM_H_

from __future__ import annotations

from dataclasses import dataclass
from tilelang import tvm as tvm
from tvm.target import Target
from tvm.ir import Range
from tvm import tirx
from tilelang import language as T
from tilelang.utils.language import is_shared, is_fragment, is_tensor_memory
from tilelang.tileop.base import GemmWarpPolicy
from tilelang.language.dtypes import validate_gemm_ab_dtypes
from tvm.ir.base import Node
from tvm.ir import PrimExpr


@dataclass
class GemmBase:
    """Base class for GEMM tile operators.

    Classifies the GEMM variant by the memory scopes of operands A and B
    (SS, SR, RS, TS, RR) and provides common property accessors for the
    underlying ``gemm_node`` IR node.
    """

    gemm_node: Node

    def __post_init__(self) -> None:
        validate_gemm_ab_dtypes(
            self.A.dtype,
            self.B.dtype,
            a_in_tmem=is_tensor_memory(self.A),
            allow_f8f6f4_mixed=self.allow_f8f6f4_mixed_dtypes,
        )

    @property
    def allow_f8f6f4_mixed_dtypes(self) -> bool:
        # TODO(wt): Consider enabling mixed f8f6f4 operands for MMA paths too.
        return False

    def infer_layout(self, target: Target, thread_nums: int):
        raise NotImplementedError("infer_layout is not implemented")

    def lower(
        self,
        layout_map: dict,
        target: Target,
        thread_bounds: Range,
        thread_var: tirx.Var,
        mbar_phase_expr: tirx.PrimExpr | None = None,
    ):
        raise NotImplementedError("lower is not implemented")

    def is_gemm_ss(self) -> bool:
        """Return True if both A and B are in shared memory (SS variant)."""
        return is_shared(self.A) and is_shared(self.B)

    def is_gemm_sr(self) -> bool:
        """Return True if A is in shared memory and B is in registers (SR variant)."""
        return is_shared(self.A) and is_fragment(self.B)

    def is_gemm_rs(self) -> bool:
        """Return True if A is in registers and B is in shared memory (RS variant)."""
        return is_fragment(self.A) and is_shared(self.B)

    def is_gemm_ts(self) -> bool:
        """Return True if A is in tensor memory and B is in shared memory (TS variant)."""
        return is_tensor_memory(self.A) and is_shared(self.B)

    def is_gemm_rr(self) -> bool:
        """Return True if both A and B are in registers (RR variant)."""
        return is_fragment(self.A) and is_fragment(self.B)

    @property
    def M(self) -> int:
        return getattr(self.gemm_node, "m", None)

    @property
    def N(self) -> int:
        return getattr(self.gemm_node, "n", None)

    @property
    def K(self) -> int:
        return getattr(self.gemm_node, "k", None)

    @property
    def trans_A(self) -> bool:
        return getattr(self.gemm_node, "transA", None)

    @property
    def trans_B(self) -> bool:
        return getattr(self.gemm_node, "transB", None)

    @property
    def a_dtype(self):
        """A operand dtype."""
        return self.A.dtype

    @property
    def b_dtype(self):
        """B operand dtype."""
        return self.B.dtype

    @property
    def accum_dtype(self) -> str:
        return self.C.dtype

    @property
    def chunk(self) -> int:
        """
        Get the logical compute width for the GEMM instruction.
        Prioritizes the actual sliced extent from ARegion over physical buffer size.
        """
        if self.ARegion is not None:
            k_axis = -2 if self.trans_A else -1
            return self.ARegion.region[k_axis].extent
        if self.K is not None:
            return self.K
        return self.A.shape[-2] if self.trans_A else self.A.shape[-1]

    @property
    def A(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "a", None)

    @property
    def B(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "b", None)

    @property
    def C(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "c", None)

    @property
    def ARegion(self):
        return getattr(self.gemm_node, "aRegion", None)

    @property
    def BRegion(self):
        return getattr(self.gemm_node, "bRegion", None)

    @property
    def CRegion(self):
        return getattr(self.gemm_node, "cRegion", None)

    @property
    def stride_A(self) -> int:
        return getattr(self.gemm_node, "strideA", None)

    @property
    def stride_B(self) -> int:
        return getattr(self.gemm_node, "strideB", None)

    @property
    def offset_A(self) -> int:
        return getattr(self.gemm_node, "offsetA", None)

    @property
    def offset_B(self) -> int:
        return getattr(self.gemm_node, "offsetB", None)

    @property
    def clear_accum(self) -> PrimExpr:
        return getattr(self.gemm_node, "clearAccum", None)

    @property
    def k_pack(self) -> int:
        return getattr(self.gemm_node, "kPack", None)

    @property
    def wg_wait(self) -> int:
        return getattr(self.gemm_node, "wgWait", 0)

    @property
    def is_tcgen05(self) -> bool:
        return getattr(self.gemm_node, "isTcgen05", False)

    @property
    def policy(self) -> GemmWarpPolicy:
        return getattr(self.gemm_node, "policy", None)

    @property
    def mbarptr(self) -> PrimExpr:
        return getattr(self.gemm_node, "mbarPtr", tvm.tirx.const(0, T.uint32))

    @property
    def mbar(self) -> tirx.BufferLoad | None:
        return getattr(self.gemm_node, "mbar", None)

    @property
    def C_coords(self):
        coords = getattr(self.gemm_node, "cCoords", None)
        if coords is None or len(coords) == 0:
            zero = tvm.tirx.const(0, T.int32)
            return [zero, zero]
        return [coords[i] for i in range(len(coords))]

    @property
    def SFARegion(self):
        return getattr(self.gemm_node, "sfaRegion", None)

    @property
    def SFBRegion(self):
        return getattr(self.gemm_node, "sfbRegion", None)

    @property
    def sf_k_start(self) -> PrimExpr:
        return getattr(self.gemm_node, "sfKStart", tvm.tirx.const(0, T.int32))

    @property
    def is_blockscaled(self) -> bool:
        return self.SFARegion is not None and self.SFBRegion is not None

    def get_region_base_offsets(self, region):
        """
        Get the base offset (start index) for each dimension from a BufferRegion.

        For example, if region is A_shared[ko % 2, 0:128, 0:64],
        this returns [ko % 2, 0, 0]

        Args:
            region: BufferRegion object

        Returns:
            List of PrimExpr representing the base offset for each dimension
        """
        if region is None:
            return []
        return [r.min for r in region.region]

    @property
    def A_base_offsets(self):
        """Get base offsets for each dimension of A region"""
        return self.get_region_base_offsets(self.ARegion)

    @property
    def B_base_offsets(self):
        """Get base offsets for each dimension of B region"""
        return self.get_region_base_offsets(self.BRegion)

    @property
    def C_base_offsets(self):
        """Get base offsets for each dimension of C region"""
        return self.get_region_base_offsets(self.CRegion)

"""CUDA GEMM op registrations."""

from __future__ import annotations

from tilelang.tileop.gemm.registry import register_gemm_impl
from .gemm_mma import GEMM_INST_MMA, GemmMMA
from .gemm_mma_sm70 import GemmMMASm70
