def _match_wmma(target) -> bool:
    return target_is_hip(target)


register_gemm_impl("rocm.mfma", GEMM_INST_MFMA, _match_mfma, GemmMFMA)
register_gemm_impl("rocm.wmma", GEMM_INST_WMMA, _match_wmma, GemmWMMA)

